// ============================================================
// CONFIGURE: Define your agents for round-robin assignment
// ============================================================
const AGENTS = [
  { id: '111111111', name: 'Agent One',   email: 'agent1@example.com' },
  { id: '222222222', name: 'Agent Two',   email: 'agent2@example.com' },
  { id: '333333333', name: 'Agent Three', email: 'agent3@example.com' }
];

const ORG_ID = 'YOUR_ORG_ID'; // Zoho Desk Org ID
// ============================================================

const body = $input.first().json.body || $input.first().json;
const ticketId = body.ticketId || body.ticket?.id;
const channel = body.channel || 'unknown';

if (!ticketId) {
  return [{ json: { error: 'No ticketId found in webhook payload', body } }];
}

// Round-robin via Static Data
const staticData = $getWorkflowStaticData('global');
let lastIndex = staticData.lastAgentIndex ?? -1;
let nextIndex = (lastIndex + 1) % AGENTS.length;
staticData.lastAgentIndex = nextIndex;

const agent = AGENTS[nextIndex];

return [{
  json: {
    ticketId,
    channel,
    assigneeId: agent.id,
    assigneeName: agent.name,
    assigneeEmail: agent.email,
    orgId: ORG_ID,
    agentIndex: nextIndex,
    totalAgents: AGENTS.length
  }
}];

// Parse the Zoho Desk response and log the assignment result
const raw = $input.first().json.data;
let result;
try {
  result = JSON.parse(raw);
} catch (e) {
  result = { raw };
}

const prev = $('Round Robin Select Agent').first().json;

return [{
  json: {
    success: !result.errorCode,
    ticketId: prev.ticketId,
    assignedTo: prev.assigneeName,
    agentIndex: prev.agentIndex,
    response: result
  }
}];
